import{_ as a,o as t,c as r,a2 as s}from"./chunks/framework.gTi9JjtA.js";const y=JSON.parse('{"title":"Interface: CantonVerifyContext","description":"","frontmatter":{},"headers":[],"relativePath":"api/@chainsafe/x402-core/interfaces/CantonVerifyContext.md","filePath":"api/@chainsafe/x402-core/interfaces/CantonVerifyContext.md"}'),i={name:"api/@chainsafe/x402-core/interfaces/CantonVerifyContext.md"};function n(o,e,c,d,h,p){return t(),r("div",null,[...e[0]||(e[0]=[s('<h1 id="interface-cantonverifycontext" tabindex="-1">Interface: CantonVerifyContext <a class="header-anchor" href="#interface-cantonverifycontext" aria-label="Permalink to &quot;Interface: CantonVerifyContext&quot;">​</a></h1><p>Defined in: <a href="https://github.com/ChainSafe/canton-x402-sdk/blob/e2c94df0e9ba8bbb04710c055a87c9081ae252c2/packages/x402-core/src/types/facilitator.ts#L65" target="_blank" rel="noreferrer">packages/x402-core/src/types/facilitator.ts:65</a></p><p>What the CALLER resolves before a Canton <code>exact</code> payment can be verified. The mirror of <code>extensions</code> on the way out: facts in, facts out, both scheme-shaped.</p><h2 id="properties" tabindex="-1">Properties <a class="header-anchor" href="#properties" aria-label="Permalink to &quot;Properties&quot;">​</a></h2><h3 id="payerpublickeys" tabindex="-1">payerPublicKeys <a class="header-anchor" href="#payerpublickeys" aria-label="Permalink to &quot;payerPublicKeys&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">payerPublicKeys</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: readonly string[];</span></span></code></pre></div><p>Defined in: <a href="https://github.com/ChainSafe/canton-x402-sdk/blob/e2c94df0e9ba8bbb04710c055a87c9081ae252c2/packages/x402-core/src/types/facilitator.ts#L77" target="_blank" rel="noreferrer">packages/x402-core/src/types/facilitator.ts:77</a></p><p>The payer party&#39;s PUBLIC signing keys, STANDARD base64 Ed25519 — not base64url, which is what a JWKS <code>x</code> is: most keys spell differently in the two, and an undecodable one is silently just a key that did not sign.</p><p>Read from the ledger by the caller, because the payload carries none and the payer is the transfer&#39;s sender (<a href="./../functions/decodePayloadTransfer.html">decodePayloadTransfer</a>). A party may publish several and the payload does not say which signed, so any one verifying is the party verifying; none refuses the payment. Which one did verify comes back as <code>extensions.signedBy</code>.</p><hr><h3 id="registryparties" tabindex="-1">registryParties? <a class="header-anchor" href="#registryparties" aria-label="Permalink to &quot;registryParties?&quot;">​</a></h3><div class="language-ts vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">ts</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">registryParties</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">?:</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Readonly</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Record</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&lt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">string, readonly string[]</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">;</span></span></code></pre></div><p>Defined in: <a href="https://github.com/ChainSafe/canton-x402-sdk/blob/e2c94df0e9ba8bbb04710c055a87c9081ae252c2/packages/x402-core/src/types/facilitator.ts#L109" target="_blank" rel="noreferrer">packages/x402-core/src/types/facilitator.ts:109</a></p><p>The registry infrastructure parties trusted for each registrar, keyed by the registrar&#39;s party id (an instrument&#39;s <code>instrumentId.admin</code>). For the DA Registry Utility, that is its operator and the token&#39;s provider.</p><p>Spec Rule 7 trusts such a party only when the facilitator is configured with it for that registrar. So for a registry token (any instrument but Canton Coin), each signatory of the <code>TransferRule</code> the payment delivers through, the rule&#39;s own <code>operator</code> and <code>provider</code>, and each input holding&#39;s <code>operator</code> and <code>provider</code> must be the registrar itself or one of the parties listed for it. They are compared as a set, not by role: the list says who is trusted, not which field each one fills.</p><p>It is also what spec Rule 3&#39;s registry check reads. A registry token&#39;s transfer must exercise the receiver&#39;s own registry <code>TransferPreapproval</code> (<code>Utility.Registry.App.V0.Model.TransferPreapproval</code>), signed by <code>payTo</code> alone and naming <code>payTo</code> as receiver and the instrument&#39;s admin, for a registrar with an entry here. Otherwise verify answers <code>invalid_exact_canton_malformed_payload</code> with a <code>factory_</code> detail: <code>factory_not_preapproval</code> when the payee has no preapproval at all, and <code>factory_registry_unconfigured</code> for a registrar with no entry, which this check reaches before the one above.</p><p>Optional, and OPT-IN. Leave it out (or pass <code>undefined</code>) and neither check runs, as before they existed: registry infrastructure parties and a registry token&#39;s factory are then not checked at all. Pass it — even <code>{}</code> — and it is authoritative: a registrar with no entry is one nobody configured, and its tokens are refused. So are they when the value is not an object at all, or when the registrar&#39;s entry is not a list; members of a list that are not strings are ignored. Canton Coin ignores the field.</p>',17)])])}const f=a(i,[["render",n]]);export{y as __pageData,f as default};
